//! The database's password comes from the sealed env relay, never from MMDS, and it arrives only as a SCRAM-SHA-256 verifier.
//!
//! The password is generated by the node's postgres driver (the platform-generated secrets of the Beyond repo), sealed to the tenant's node key
//! and stored by the API as a sealed variable: nothing central ever holds it. The driver derives a verifier from it on the node (RFC 5802/7677,
//! `SCRAM-SHA-256$4096:<salt>$<StoredKey>:<ServerKey>`, a fresh salt each delivery) and hands the guest only that: this VM can check a login and
//! cannot present the password. PID 1 asks for it over the substrate vsock it already owns, the way every guest asks its driver for its env, and
//! writes it into the metadata file the supervisor reads, before the supervisor starts. initdb takes the verifier as the superuser's password
//! as it is, and the supervisor's `post_start` runs `ALTER ROLE postgres PASSWORD '<verifier>'` on EVERY start (PostgreSQL stores a verifier
//! as given), so a data directory that carries another instance's role hash (a fork, a restore) takes this instance's value. A value that is
//! not a verifier (a driver from before this) is never kept, written or used: the ask repeats and, past [`WAIT`], init exits.
//!
//! Wire (`rustlib/wire` `env.rs` and `rustlib/vsock-protocol` in the Beyond repo, mirrored here so this repo builds standalone and pinned by the
//! tests below): the ask is an `AppMessage` (0x20) whose bytes are `[0xE1]`; the answer is an `AppMessage` whose bytes are `[0xE2][msgpack
//! {generation, vars}]`. The ask is repeated every second until answered: the driver answers only once the API has stored the value.
//!
//! Fail closed: with a substrate and no value after [`WAIT`], init exits (the VM never serves a database with a password nobody can name). With
//! no substrate at all (the Docker test image) the metadata file is used as it is.

use std::collections::BTreeMap;
use std::sync::{Condvar, Mutex};
use std::time::Duration;

use serde::{Deserialize, Serialize};

/// Guest -> driver: "send me my env". `wire::nats::PLATFORM_ENV_REQUEST_KIND`.
pub const ASK_KIND: u8 = 0xE1;
/// Driver -> guest: the env. `wire::nats::PLATFORM_ENV_KIND`.
pub const ANSWER_KIND: u8 = 0xE2;
/// `vsock_protocol::MessageType::AppMessage`.
pub const MSG_APP: u8 = 0x20;
/// How often the ask is repeated until it is answered.
pub const ASK_EVERY: Duration = Duration::from_secs(1);
/// How long init waits for the password before it gives up (and the VM with it).
pub const WAIT: Duration = Duration::from_secs(300);
/// The one variable the supervisor needs from the relay.
pub const PASSWORD_KEY: &str = "POSTGRES_PASSWORD";
/// What a SCRAM-SHA-256 verifier starts with (PostgreSQL's `rolpassword` form).
pub const VERIFIER_PREFIX: &str = "SCRAM-SHA-256$";

#[derive(Serialize, Deserialize)]
struct AppMessage {
    #[serde(with = "serde_bytes")]
    bytes: Vec<u8>,
}

#[derive(Deserialize)]
struct EnvPayload {
    #[allow(dead_code)]
    generation: u64,
    vars: BTreeMap<String, String>,
}

/// What the wait ended with.
#[derive(Debug, PartialEq, Eq)]
pub enum Outcome {
    /// The relay answered with the password's verifier.
    Password(String),
    /// There is no substrate (no AF_VSOCK): the metadata file is used as it is.
    NoSubstrate,
    /// A substrate, and no password within the wait.
    TimedOut,
}

#[derive(Default)]
struct State {
    password: Option<String>,
    no_substrate: bool,
}

static STATE: Mutex<State> = Mutex::new(State {
    password: None,
    no_substrate: false,
});
static CV: Condvar = Condvar::new();

fn state() -> std::sync::MutexGuard<'static, State> {
    STATE.lock().unwrap_or_else(|e| e.into_inner())
}

/// True until a password has arrived: the substrate loop keeps asking.
pub fn needs_password() -> bool {
    state().password.is_none()
}

/// The substrate's first connect failed: there is none, so nothing will ever answer.
pub fn no_substrate() {
    state().no_substrate = true;
    CV.notify_all();
}

/// The ask, as a complete substrate frame `[len][0x20][msgpack {bytes: [0xE1]}]`.
pub fn ask_frame() -> Vec<u8> {
    let body = rmp_serde::to_vec_named(&AppMessage {
        bytes: vec![ASK_KIND],
    })
    .expect("an AppMessage encodes");
    let mut frame = ((body.len() as u32) + 1).to_be_bytes().to_vec();
    frame.push(MSG_APP);
    frame.extend_from_slice(&body);
    frame
}

/// An inbound `AppMessage` payload (the msgpack after the type byte). If it is an env answer holding the password's verifier, keep it and wake
/// the waiter; a password that is not a verifier is dropped here, so no plaintext is ever held. Anything else (another primitive message, a malformed or empty answer) is ignored: the ask repeats.
pub fn offer(app_payload: &[u8]) {
    let Ok(msg) = rmp_serde::from_slice::<AppMessage>(app_payload) else {
        return;
    };
    let Some((&kind, rest)) = msg.bytes.split_first() else {
        return;
    };
    if kind != ANSWER_KIND {
        return;
    }
    let Ok(env) = rmp_serde::from_slice::<EnvPayload>(rest) else {
        return;
    };
    if let Some(pw) = env.vars.get(PASSWORD_KEY).filter(|p| p.starts_with(VERIFIER_PREFIX)) {
        state().password = Some(pw.clone());
        CV.notify_all();
    }
}

/// Block until the relay has answered, there is no substrate, or `timeout` passes.
pub fn wait(timeout: Duration) -> Outcome {
    let deadline = std::time::Instant::now() + timeout;
    let mut st = state();
    loop {
        if let Some(pw) = &st.password {
            return Outcome::Password(pw.clone());
        }
        if st.no_substrate {
            return Outcome::NoSubstrate;
        }
        let left = deadline.saturating_duration_since(std::time::Instant::now());
        if left.is_zero() {
            return Outcome::TimedOut;
        }
        st = CV
            .wait_timeout(st, left)
            .unwrap_or_else(|e| e.into_inner())
            .0;
    }
}

/// `metadata` with the relay's password in it, and no other source of one: the supervisor reads `latest.meta-data.POSTGRES_PASSWORD`.
pub fn with_password(mut metadata: serde_json::Value, password: &str) -> serde_json::Value {
    if !metadata["latest"]["meta-data"].is_object() {
        metadata["latest"] = serde_json::json!({ "meta-data": {} });
    }
    metadata["latest"]["meta-data"][PASSWORD_KEY] = serde_json::Value::String(password.to_string());
    metadata
}

/// Without a password at all: drop whatever MMDS carried, so a stale or planted value is never the one a database starts with.
pub fn without_password(mut metadata: serde_json::Value) -> serde_json::Value {
    if let Some(m) = metadata["latest"]["meta-data"].as_object_mut() {
        m.remove(PASSWORD_KEY);
    }
    metadata
}

#[cfg(test)]
mod tests {
    use super::*;

    fn answer(vars: &[(&str, &str)]) -> Vec<u8> {
        let mut bytes = vec![ANSWER_KIND];
        let payload = serde_json::json!({ "generation": 3, "vars": vars.iter().cloned().collect::<BTreeMap<_, _>>() });
        // Named-field msgpack, as `vsock_protocol::encode` writes it.
        bytes.extend(rmp_serde::to_vec_named(&payload).unwrap());
        rmp_serde::to_vec_named(&AppMessage { bytes }).unwrap()
    }

    /// Pins the ask against the host's `AppMessagePayload` decoder: BE length, 0x20, a msgpack map {bytes: bin [0xE1]}.
    #[test]
    fn the_ask_frame_is_stable() {
        let f = ask_frame();
        assert_eq!(
            u32::from_be_bytes(f[0..4].try_into().unwrap()) as usize,
            f.len() - 4
        );
        assert_eq!(f[4], MSG_APP);
        let m: AppMessage = rmp_serde::from_slice(&f[5..]).unwrap();
        assert_eq!(m.bytes, vec![ASK_KIND]);
        // bin, not an array of ints: the host's `serde_bytes` field only reads a bin ({bytes: bin8 [0xE1]}).
        assert!(f[5..].windows(3).any(|w| w == [0xc4, 0x01, ASK_KIND]));
    }

    #[test]
    fn only_an_answer_with_a_password_counts() {
        // Not tied to the global: parse by hand.
        let ok = answer(&[(PASSWORD_KEY, "pw"), ("OTHER", "x")]);
        let m: AppMessage = rmp_serde::from_slice(&ok).unwrap();
        assert_eq!(m.bytes[0], ANSWER_KIND);
        let env: EnvPayload = rmp_serde::from_slice(&m.bytes[1..]).unwrap();
        assert_eq!(env.vars.get(PASSWORD_KEY).map(String::as_str), Some("pw"));
    }

    #[test]
    fn offer_wakes_the_waiter_and_empty_or_foreign_messages_do_not() {
        // One test owns the global state (tests share the process).
        *state() = State::default();
        offer(&answer(&[("OTHER", "x")]));
        offer(&answer(&[(PASSWORD_KEY, "")]));
        let mut foreign = rmp_serde::to_vec_named(&AppMessage {
            bytes: vec![0x0c, 1, 2],
        })
        .unwrap();
        offer(&foreign);
        foreign.clear();
        // A plaintext password (a driver from before verifiers) is never kept: the wait times out and init exits.
        offer(&answer(&[(PASSWORD_KEY, "s3cret")]));
        assert!(needs_password());
        assert_eq!(wait(Duration::from_millis(20)), Outcome::TimedOut);
        let verifier = format!("{VERIFIER_PREFIX}4096:c2FsdA==$a:b");
        let v2 = verifier.clone();
        let t = std::thread::spawn(move || {
            std::thread::sleep(Duration::from_millis(30));
            offer(&answer(&[(PASSWORD_KEY, &v2)]));
        });
        assert_eq!(wait(Duration::from_secs(5)), Outcome::Password(verifier));
        t.join().unwrap();
        assert!(!needs_password());
        *state() = State::default();
        no_substrate();
        assert_eq!(wait(Duration::from_secs(1)), Outcome::NoSubstrate);
        *state() = State::default();
    }

    #[test]
    fn the_password_replaces_any_mmds_value_and_its_absence_removes_one() {
        let mmds = serde_json::json!({"latest": {"meta-data": {"POSTGRES_PASSWORD": "stale", "BEYOND_PG_TIER": "single"}}});
        let with = with_password(mmds.clone(), "fresh");
        assert_eq!(with["latest"]["meta-data"]["POSTGRES_PASSWORD"], "fresh");
        assert_eq!(with["latest"]["meta-data"]["BEYOND_PG_TIER"], "single");
        assert!(
            without_password(mmds)["latest"]["meta-data"]
                .get("POSTGRES_PASSWORD")
                .is_none()
        );
        assert_eq!(
            with_password(serde_json::json!({}), "p")["latest"]["meta-data"]["POSTGRES_PASSWORD"],
            "p"
        );
    }
}
